QCU_T("es", "histoireKine", {
  "0": ["¿Qué tipo de medio utiliza la fisioterapia como herramienta terapéutica?",["Los agentes físicos","Los agentes farmacológicos","Los agentes quirúrgicos"],["El curso define la fisioterapia como el uso de agentes físicos como medio terapéutico.","El curso califica por el contrario a la fisioterapia de « terapéutica sin medicamentos ».","La cirugía no pertenece a los medios de la fisioterapia, que se basa en agentes físicos."]],
  "1": ["Etimológicamente, ¿qué significa « agente físico »?",["Lo que actúa en la naturaleza","Lo que cura mediante la palabra","Lo que mide el dolor"],["El curso precisa: agente = « lo que actúa », físico = « de la naturaleza ».","La etimología remite a la acción en la naturaleza, no a la comunicación.","El agente físico es una herramienta de acción terapéutica, no un instrumento de medida."]],
  "2": ["Entre las categorías de agentes físicos, ¿cuál corresponde al movimiento?",["Los agentes cinéticos","Los agentes elementales","Los agentes electromagnéticos"],["El curso clasifica el movimiento (movilizaciones, trabajo activo, vibraciones) entre los agentes cinéticos.","Los agentes elementales son los de la naturaleza: calor, frío, agua, sol, tierra, sonido.","Los agentes electromagnéticos agrupan los recursos eléctricos y las radiaciones no ionizantes."]],
  "3": ["Según el curso, ¿a qué corresponden los agentes físicos llamados « elementales »?",["Los que se encuentran en la naturaleza","Las corrientes eléctricas de todas sus formas","Las movilizaciones y el trabajo activo"],["El curso los define como el calor, el frío, el agua, el sol, la tierra y el sonido presentes en la naturaleza.","Esos recursos eléctricos corresponden a los agentes electromagnéticos.","El movimiento y las movilizaciones corresponden a los agentes cinéticos."]],
  "4": ["¿Cómo califica el curso a la fisioterapia en cuanto a su naturaleza?",["Una ciencia y un arte del tratamiento físico","Una especialidad quirúrgica de rehabilitación","Una rama de los cuidados de enfermería"],["El curso define la fisioterapia como « la ciencia y el arte del tratamiento físico ».","La fisioterapia no es una especialidad quirúrgica, sino un tratamiento mediante agentes físicos.","El curso insiste: fisioterapia ≠ cuidados de enfermería."]],
  "5": ["¿Por qué se considera también la fisioterapia como un « arte »?",["Exige competencias prácticas, creativas y humanas adaptadas a cada paciente","Se basa únicamente en la aplicación de protocolos estandarizados","Corresponde a la producción de obras estéticas"],["El curso cita destreza manual, personalización, empatía y creatividad.","Al contrario, el arte implica la personalización del tratamiento, no su estandarización.","El término « arte » remite aquí a las competencias clínicas, no a la estética."]],
  "6": ["¿Cuál es el fin último de la fisioterapia según el curso?",["Mejorar la calidad de vida y facilitar la reintegración social","Establecer el diagnóstico etiológico de las enfermedades","Prescribir los tratamientos farmacológicos adecuados"],["El curso busca promover la salud para mejorar la calidad de vida y la plena reintegración social.","El diagnóstico etiológico corresponde a la CIE; el fin es funcional y social.","La fisioterapia es una terapéutica sin medicamentos."]],
  "7": ["Según el marco teórico actual del curso, la fisioterapia es una profesión:",["Independiente, que no requiere la supervisión de otros profesionales","Subordinada de forma permanente al médico rehabilitador","Vinculada jerárquicamente a los cuidados de enfermería"],["El resumen del curso la presenta como una profesión independiente no supervisada.","El curso afirma que el fisioterapeuta no depende del médico rehabilitador.","El curso distingue claramente fisioterapia y cuidados de enfermería."]],
  "8": ["¿En qué año adoptó la OMS la CIF, clasificación del funcionamiento, de la discapacidad y de la salud?",["En 2001","En 1980","En 1968"],["El curso indica que la CIF fue adoptada en 2001 por la OMS.","1980 corresponde a la antigua CIDDM, de la que la CIF es la evolución.","1968 es la fecha de la definición de la fisioterapia por la OMS, no de la CIF."]],
  "9": ["¿Qué clasifica principalmente la CIF?",["El funcionamiento y la discapacidad relacionados con la salud","Las enfermedades según su etiología","A los individuos según su discapacidad"],["El curso precisa que la CIF describe el funcionamiento humano y no las etiologías.","Son los estados de salud los que se clasifican por etiología en la CIE-11, no en la CIF.","El curso subraya que la CIF no clasifica personas, sino estados de salud."]],
  "10": ["Según el curso, ¿cómo se define una ciencia?",["Un conocimiento asociado a un método","Una opinión compartida por una mayoría de expertos","Una creencia transmitida de generación en generación"],["El curso resume: Ciencia = Conocimiento + Método.","La ciencia se basa en un método verificable, no en un consenso de opiniones.","El curso opone el conocimiento científico al conocimiento espontáneo de la vida diaria."]],
  "11": ["¿Cuáles son las características fundamentales del conocimiento científico según el curso?",["Objetividad, racionalidad y sistematicidad","Subjetividad, intuición y espontaneidad","Creatividad, empatía y comunicación"],["El curso cita exactamente esas tres características fundamentales.","Son los rasgos del conocimiento cotidiano, opuesto al conocimiento científico.","Esas cualidades corresponden al « arte » de la fisioterapia, no a los criterios de cientificidad."]],
  "12": ["¿En qué consiste la práctica basada en la evidencia en fisioterapia?",["Integrar la experiencia clínica con las mejores pruebas científicas y las preferencias del paciente","Aplicar únicamente la experiencia personal del profesional","Seguir exclusivamente las indicaciones de un superior jerárquico"],["El curso define la PBE por la integración de la experiencia clínica, las pruebas y el paciente.","La PBE va más allá de la sola experiencia al añadirle las pruebas científicas y el paciente.","La PBE se basa en las pruebas y en la decisión clínica compartida, no en la jerarquía."]],
  "13": ["¿Qué pueblo de la Antigüedad inventó la escritura cuneiforme, grabada en tablillas de arcilla?",["Los sumerios","Los egipcios","Los aztecas"],["El curso indica que los sumerios (3500-2000 a. C.) inventaron la escritura cuneiforme grabada en tablillas de arcilla.","El Egipto antiguo se asocia a las primeras terapias manuales y al papiro de Edwin Smith, no a la escritura cuneiforme.","Las civilizaciones precolombinas empleaban duchas de vapor seguidas de frío, pero no la escritura cuneiforme."]],
  "14": ["Según el curso, ¿quién se presenta como el primer médico conocido, autor del papiro de Edwin Smith?",["Imhotep","Hipócrates","Galeno"],["El curso atribuye el papiro de Edwin Smith a Imhotep, presentado como el primer médico conocido.","Hipócrates es el « Padre de la medicina » en la Grecia antigua, posterior a Imhotep.","Galeno es un médico de la Roma antigua; no redactó el papiro de Edwin Smith."]],
  "15": ["En el Egipto antiguo, ¿cómo recomendaba el papiro de Edwin Smith emplear el frío?",["En las etapas iniciales de la inflamación","Para la tonificación muscular diaria","En las etapas tardías de la cicatrización"],["El curso precisa que el frío se empleaba en las etapas iniciales de la inflamación, y el calor en las más tardías.","La tonificación mediante baño (frío/caliente) corresponde a Asclepíades de Bitinia en Grecia, no al papiro egipcio.","Según el curso, es el calor el que se empleaba en las etapas más tardías, no el frío."]],
  "16": ["En la China antigua, ¿a qué personaje se atribuye el libro de medicina « Nei-Ching »?",["El emperador Amarillo Huangdi","Tzu Kuo Shih","Chu'n Yu"],["El curso indica que el emperador Amarillo Huangdi (2697-2597 a. C.) escribió el « Nei-Ching ».","Tzu Kuo Shih escribió sobre la terapia QiGong, no el Nei-Ching.","Chu'n Yu redactó un compendio de observaciones médicas, pero no el Nei-Ching."]],
  "17": ["Según el « Nei-Ching » presentado en el curso, la enfermedad corresponde a un desequilibrio entre:",["el Yin y el Yang","los cuatro humores del cuerpo","el cuerpo y el espíritu según Descartes"],["El curso indica que la enfermedad es un desequilibrio entre el Yin y el Yang, y que el masaje restablece ese equilibrio.","La teoría de los cuatro humores corresponde al Corpus hipocrático griego, no al Nei-Ching chino.","La separación cuerpo/espíritu remite a Descartes (Renacimiento), no al Nei-Ching."]],
  "18": ["¿Qué terapia de la India antigua se presenta en el curso como próxima a la fisioterapia?",["El yoga","La acupuntura","La hidroterapia termal"],["El curso presenta el yoga como la principal aportación de la época, una terapia que se aproximaría a la fisioterapia.","La acupuntura se asocia a la China antigua (Tzu Kuo Shih), no a la India.","La hidroterapia termal la desarrolla sobre todo Asclepíades en Grecia, no la India antigua."]],
  "19": ["¿Cómo se apoda a Hipócrates en el curso?",["El Padre de la medicina","El Padre de la osteopatía","El Padre de la gimnasia sueca"],["El curso designa a Hipócrates de Cos como el « Padre de la medicina ».","El padre de la osteopatía es Andrew Taylor Still (siglo XX), no Hipócrates.","El padre de la gimnasia sueca es Pehr Henrik Ling (siglo XIX)."]],
  "20": ["¿En qué teoría se basa la concepción de la salud en el Corpus hipocrático?",["La teoría de los cuatro humores","La teoría del Yin y del Yang","La teoría de la energía meridional"],["El curso indica que la salud está ligada al equilibrio de los cuatro humores: sangre, bilis negra, bilis amarilla y flema.","El Yin y el Yang corresponden a la medicina china (Nei-Ching), no al Corpus hipocrático.","El flujo meridiano (energía vital) es propio de la acupuntura, no del Corpus hipocrático."]],
  "21": ["En la Edad Media, ¿cuál era la situación del ejercicio físico según el curso?",["Estaba prohibido, pues el culto al alma primaba sobre el del cuerpo","Era obligatorio en las escuelas","Se clasificaba según la duración y la intensidad"],["El curso indica una interrupción del ejercicio físico, prohibido porque el culto al alma es más importante que el del cuerpo.","La enseñanza obligatoria de la gimnasia en las escuelas es obra de Ling en el siglo XIX, no de la Edad Media.","La clasificación por duración e intensidad es la de Diocles de Caristo en la Grecia antigua."]],
  "22": ["¿Quién se considera en el curso el fundador de la anatomía moderna en el Renacimiento?",["Andrés Vesalio","Ambroise Paré","Nicolas Andry de Bois-Regard"],["El curso indica que Andrés Vesalio (1514-1564) se considera el fundador de la anatomía moderna.","Ambroise Paré desarrolló la primera prótesis de pierna, pero no se cita como fundador de la anatomía moderna.","Nicolas Andry introdujo la palabra « Ortopedia »; no es el fundador de la anatomía moderna."]],
  "23": ["¿Quién introdujo la palabra « Ortopedia » según el curso?",["Nicolas Andry de Bois-Regard","Francisco Arceo","Joseph Clément Tissot"],["El curso indica que Nicolas Andry de Bois-Regard (1658-1742) introdujo la palabra Ortopedia (orthos paidos; recto niño).","Francisco Arceo inventó la bota ortopédica para el pie equinovaro, pero no introdujo la palabra Ortopedia.","Tissot insistía en el ejercicio como alternativa a la cirugía; no introdujo la palabra Ortopedia."]],
  "24": ["¿Quién se presenta en el curso como el padre de la Gimnasia Sueca?",["Pehr Henrik Ling","Gustav Zander","Vincenz Priessnitz"],["El curso designa a Pehr Henrik Ling (1776-1839) como el padre de la Gimnasia Sueca (ejercicios en el suelo).","Gustav Zander es el inventor de la mecanoterapia, no de la gimnasia sueca.","Priessnitz se considera el padre de la hidroterapia, no de la gimnasia sueca."]],
  "25": ["En 1845, ¿quién propone la palabra « Kinesiterapia » para designar el tratamiento de las enfermedades mediante el movimiento?",["Georgii","Gustav Zander","Duchenne de Boulogne"],["El curso indica que en 1845 Georgii propone la palabra Kinesiterapia en su libro sobre el tratamiento mediante el movimiento según el método de Ling.","Zander inventó la mecanoterapia y sus aparatos; no propuso la palabra Kinesiterapia.","Duchenne de Boulogne trabajaba sobre la faradización localizada; no propuso el término Kinesiterapia."]],
  "26": ["¿Quién es el inventor de la mecanoterapia y de sus 71 aparatos según el curso?",["Gustav Zander","Johan Georg Metzger","Just Lucas Championnière"],["El curso indica que Gustav Zander (1835-1920) es el inventor de la mecanoterapia, con 71 aparatos clasificados en 4 categorías.","Metzger se asocia al tratamiento mediante fricciones y masaje de los esguinces, no a la mecanoterapia.","Championnière recomendaba movilizaciones activas de las articulaciones adyacentes a una fractura; no inventó la mecanoterapia."]],
  "27": ["Según el curso, ¿en qué año se creó en Francia el diploma estatal de fisioterapeuta?",["El 30 de abril de 1946","En 1900","En 1951"],["El curso indica que el 30 de abril de 1946 se crea el diploma estatal de fisioterapeuta, en sustitución de la especialidad de enfermero-masajista.","En 1900 se crea la Sociedad de Kinesiterapia en Francia, no el diploma estatal.","1951 corresponde a la creación de la WCPT, no al diploma estatal francés de fisioterapeuta."]],
  "28": ["¿Qué enfoque se caracteriza por la integración de distintas disciplinas en la resolución de un problema?",["El enfoque interdisciplinar","El enfoque multidisciplinar","El enfoque tangencial"],["El curso lo define por la integración de distintas disciplinas en la resolución de un problema.","Hace trabajar varias disciplinas en paralelo sobre el mismo caso, sin integración profunda de los conocimientos.","Es un tipo de interdisciplinariedad en el que las disciplinas están en contacto pero conservan sus límites, no un enfoque de trabajo."]],
  "29": ["En el enfoque multidisciplinar, ¿cómo trabajan las distintas disciplinas sobre un mismo caso?",["En paralelo, cada una con su propia metodología y su propia visión","Integrando sus saberes para resolver juntas el problema","Tomando prestadas recíprocamente sus leyes para crear una nueva disciplina"],["El curso indica que trabajan en paralelo sin permitir una integración profunda de los conocimientos.","Es la característica del enfoque interdisciplinar, no del multidisciplinar.","Eso describe la relación total o estructural de la interdisciplinariedad."]],
  "30": ["Según el curso, ¿a qué tipo de interdisciplinariedad corresponde la fisioterapia, que se desarrolla a partir de la estructura de otras disciplinas?",["La relación total o estructural","La relación parcial o lineal","La relación tangencial"],["El curso cita la fisioterapia como ejemplo de relación total: varias disciplinas contribuyen a crear una nueva disciplina.","Corresponde a una disciplina que toma prestada una ley de otra para explicar un fenómeno.","Designa disciplinas en contacto que conservan sus límites, como la fisiología y la anatomía."]],
  "31": ["Según el curso, ¿qué riesgo puede conllevar la especialización excesiva?",["El aislamiento profesional en « silos » de conocimiento","La desaparición definitiva de las fronteras entre disciplinas","La pérdida de experiencia del investigador en su ámbito"],["El curso indica que la especialización puede conducir al aislamiento profesional en « cabañas » o « silos ».","La desaparición de las fronteras se presenta como un factor que favorece la interdisciplinariedad, no como un riesgo de la especialización.","Al contrario, la especialización permite al investigador convertirse en experto según el curso."]],
  "32": ["Según el curso, ¿con qué finalidad aparecieron los primeros programas de tratamiento del dolor en los años 1970?",["Atender a los veteranos de guerra","Formar a los fisioterapeutas en prevención","Reducir los costes hospitalarios"],["El curso precisa que esos primeros programas buscaban atender a los veteranos de guerra.","El curso no asocia esos programas a la formación de los fisioterapeutas.","El objetivo citado es la atención a los veteranos, no una finalidad económica."]],
  "33": ["¿Cuáles son las tres dimensiones del modelo biopsicosocial?",["Biológica, psicológica y social","Biológica, motora y ambiental","Física, espiritual y económica"],["El curso presenta el modelo con las dimensiones bio, psico y social.","Esas dimensiones no corresponden al modelo biopsicosocial del curso.","El modelo del curso se basa en lo biológico, lo psicológico y lo social."]],
  "34": ["Según el curso, ¿en qué se centran los « profesionales de la salud » que no tienen necesariamente una formación en el ámbito sanitario?",["La promoción de la salud y la prevención de las enfermedades mediante la educación","El diagnóstico y el tratamiento de las patologías","La inscripción en el registro nacional de profesionales sanitarios"],["El curso indica que se centran en la promoción y la prevención mediante la educación y el empoderamiento de las comunidades.","Esos actos corresponden a los profesionales sanitarios regulados y cualificados en el ámbito de la salud.","La inscripción en el registro atañe a los profesionales sanitarios regulados, no a esos perfiles."]],
  "35": ["¿Cómo define el curso la anamnesis (entrevista clínica)?",["Un instrumento de recogida de datos basado en una comunicación interpersonal de doble sentido","Una simple conversación informal con el paciente","Una exploración física estandarizada del paciente"],["El curso la presenta como un instrumento de recogida de datos que exige una comunicación interpersonal de doble sentido.","El curso precisa explícitamente que no se trata de una simple conversación.","La exploración física es distinta de la anamnesis, que es una entrevista de recogida de datos."]],
  "36": ["Entre los objetivos de la entrevista clínica, ¿cuál figura en el curso?",["Establecer una buena relación terapéutica","Prescribir directamente un tratamiento farmacológico","Sustituir la exploración física del paciente"],["El curso cita el establecimiento de una buena relación terapéutica entre los objetivos de la entrevista.","La prescripción farmacológica no figura entre los objetivos de la entrevista clínica.","La entrevista completa la recogida de datos con otros métodos; no los sustituye."]],
  "37": ["Entre las actitudes básicas del terapeuta que favorecen la relación, ¿cuál se cita en el curso?",["La escucha activa","La máxima directividad","La simpatía hacia el paciente"],["El curso enumera la escucha activa entre las actitudes básicas que favorecen la relación, junto con la empatía, la aceptación incondicional y la autenticidad.","El curso indica que tanto el exceso como la falta de directividad son negativos.","El curso distingue la empatía de la simpatía; no cita la simpatía como actitud básica."]],
  "38": ["Según el curso, ¿en qué se distingue la empatía de la simple escucha activa?",["La empatía presupone la escucha activa pero va más allá, hasta comprender el sentido más allá de lo que el paciente expresa","La empatía consiste solo en reformular lo que dice el paciente","La empatía se limita a sentir la misma emoción que el paciente"],["El curso precisa que la empatía presupone una escucha activa pero va más allá.","La reformulación corresponde a la paráfrasis, una habilidad de escucha, no a la empatía.","El curso distingue la empatía de la simpatía y de la compasión."]],
  "39": ["¿Qué tipo de entrevista clínica se considera que ofrece un grado aceptable de flexibilidad conservando una uniformidad suficiente?",["La entrevista semiestructurada","La entrevista estructurada","La entrevista no estructurada"],["El curso indica que las entrevistas semiestructuradas ofrecen flexibilidad y una uniformidad suficiente para interpretaciones coherentes.","Aplica rigurosamente preguntas predefinidas, con el inconveniente de una falta de flexibilidad.","Es muy flexible, pero puede dejar lagunas en las informaciones necesarias."]],
  "40": ["¿Qué se pide al paciente que haga en el « mapa corporal » durante la recogida de datos?",["Dibujar las zonas de dolor, de parestesia, de quemazón o de hormigueo","Anotar la lista de sus medicamentos y alergias","Valorar él mismo su fuerza muscular"],["El curso indica que se pide al paciente dibujar esas zonas con distintos códigos o colores.","Los medicamentos y las alergias son datos recogidos aparte, no en el mapa corporal.","Las pruebas musculares corresponden a la exploración que realiza el terapeuta, no al mapa corporal."]],
  "41": ["¿Cómo se define el razonamiento clínico en fisioterapia?",["Un proceso de reflexión y de toma de decisiones que estructura el sentido y las estrategias de atención a partir de los datos clínicos y de la elección del paciente","La aplicación estricta de un protocolo estandarizado idéntico para todos los pacientes con el mismo diagnóstico","La memorización de los conocimientos biomédicos adquiridos durante la formación inicial"],["El curso define el razonamiento clínico como un proceso de reflexión o de toma de decisiones asociado a la práctica profesional, que estructura el sentido y las estrategias de tratamiento.","El curso insiste al contrario en la adaptación a cada sujeto; los protocolos rígidos son un factor limitante, no una definición del razonamiento.","La base de conocimientos es un simple elemento del proceso, no la definición del razonamiento clínico en sí."]],
  "42": ["El razonamiento clínico en fisioterapia se describe como un proceso que es:",["Complejo, cognitivo, interactivo y multifactorial","Simple, lineal e independiente del contexto","Puramente automático y siempre consciente"],["El curso califica el razonamiento clínico de complejo, cognitivo, interactivo, imperceptible y multifactorial, dependiente del contexto.","El curso precisa al contrario que depende del contexto y que es multifactorial, por tanto ni simple ni lineal.","El curso indica que no siempre es consciente ni automático; esa formulación es inexacta."]],
  "43": ["En el razonamiento inductivo se procede:",["De algo específico hacia algo general","De algo general hacia algo específico","Autorregulando sus propios pensamientos de manera reflexiva"],["El curso define el razonamiento inductivo como el que parte de lo específico para llegar a lo general, difícil de poner en práctica.","Es la definición del razonamiento deductivo, no del inductivo, según el curso.","Se trata de la metacognición, otro proceso descrito aparte en el curso."]],
  "44": ["Según el curso, ¿cuál es la evolución típica del razonamiento con la experiencia profesional?",["Se empieza por un razonamiento deductivo que se automatiza progresivamente hacia un razonamiento casi inductivo","Se empieza por un razonamiento inductivo que se vuelve progresivamente deductivo","El modo de razonamiento permanece estrictamente idéntico a lo largo de toda la carrera"],["El curso indica que se empieza por el deductivo y que después se automatiza hasta pasar a un razonamiento inductivo casi sin darse cuenta.","El curso describe la evolución inversa: del deductivo hacia el inductivo automatizado.","El curso subraya al contrario una transformación progresiva ligada a la experiencia."]],
  "45": ["En el proceso de razonamiento, ¿a qué corresponde la metacognición?",["Al proceso de autorregulación del clínico que reflexiona sobre sus propios pensamientos de forma escéptica","A la percepción, el análisis, la síntesis y la evaluación de los datos recogidos","Al conjunto de los conocimientos biomédicos adquiridos durante la formación"],["El curso define la metacognición como la autorregulación del clínico para elaborar sus pensamientos de manera escéptica y reflexiva (pensar sobre sus pensamientos).","Esa descripción corresponde a la cognición, no a la metacognición, según el curso.","Se trata de la base de conocimientos, distinta de la metacognición en el curso."]],
  "46": ["¿En qué tipo de razonamiento se fundamenta el modelo inicial del razonamiento clínico?",["Un razonamiento hipotético-deductivo procedente del paradigma de las ciencias cognitivas","Un enfoque colaborativo centrado en las ciencias del dolor","Una interacción multidimensional entre factores biológicos, psicológicos y sociales"],["El curso indica que el modelo inicial se basa en el paradigma de las ciencias cognitivas y se caracteriza por un razonamiento hipotético-deductivo.","Es el modelo de razonamiento clínico colaborativo, no el modelo inicial.","Esa descripción corresponde al modelo biopsicosocial, no al modelo inicial."]],
  "47": ["¿Cómo describe el modelo biopsicosocial el dolor y la discapacidad?",["Como una interacción multidimensional y recíproca entre factores biológicos, psicológicos y sociales","Como el resultado directo y único de una lesión tisular objetivada en las pruebas complementarias","Como un fenómeno determinado principalmente por la colaboración entre profesionales"],["El curso describe el enfoque biopsicosocial como una interacción multidimensional, dinámica e inseparable entre factores biológicos, psicológicos y sociales.","Esa sería una visión puramente biomédica; el modelo biopsicosocial integra también lo psicológico y lo social.","El modelo biopsicosocial versa sobre la interacción de tres factores, no sobre la colaboración interprofesional."]],
  "48": ["En el modelo biopsicosocial, ¿a qué factor corresponden la kinesiofobia y el catastrofismo?",["Al factor psicológico","Al factor biológico","Al factor social"],["El curso clasifica los factores psicológicos (estrategias de afrontamiento, kinesiofobia, catastrofismo, depresión, ansiedad) en la dimensión psico.","El factor bio atañe a la nocicepción, la inflamación y las pruebas de imagen, no a la kinesiofobia.","El factor social atañe al condicionamiento cultural y a los acontecimientos vitales estresantes, no al catastrofismo."]],
  "49": ["¿Cuál es el objetivo principal de la exploración subjetiva?",["Definir el origen del problema, identificar las señales de alarma y orientar la evaluación","Confirmar o descartar las hipótesis mediante pruebas físicas específicas","Realizar una exploración física exhaustiva para reproducir los síntomas"],["El curso precisa que la exploración subjetiva busca definir el origen del problema, identificar las señales de alarma, el pronóstico y orientar las pruebas funcionales.","Es un objetivo de la exploración objetiva, que viene a reproducir las manifestaciones clínicas mediante pruebas.","La exploración física exhaustiva corresponde a la exploración objetiva, no a la subjetiva."]],
  "50": ["¿Qué elemento constituye un indicador de alarma (bandera roja) en la exploración subjetiva?",["Un dolor nocturno intenso que no se modifica con los medicamentos ni con la postura","Un dolor mecánico que empeora con el movimiento y mejora con el reposo","Un dolor intermitente de intensidad leve aparecido tras un esfuerzo"],["El curso cita el dolor nocturno intenso y el dolor no modificado por medicamentos ni postura entre las banderas rojas.","Ese comportamiento es típicamente mecánico y tranquilizador, no una bandera roja según el curso.","Un dolor leve e intermitente no figura entre los indicadores de alarma del curso."]],
  "51": ["Según el sistema de categorización de las hipótesis, ¿a qué corresponde la hipótesis de pronóstico?",["Explicar al paciente, en forma de hipótesis, la duración probable del proceso de curación","Identificar las precauciones y contraindicaciones para la exploración y el tratamiento","Determinar los mecanismos patobiológicos como la inflamación o la nocicepción"],["El curso define la hipótesis de pronóstico como la estimación, explicada al paciente, de la duración del proceso de curación, sin prometer nunca el 100 %.","Eso corresponde a la hipótesis de precauciones y contraindicaciones, una categoría distinta.","Es la hipótesis de los mecanismos patobiológicos, no la hipótesis de pronóstico."]],
  "52": ["Sobre el sistema musculoesquelético, ¿cuál es un efecto del ejercicio terapéutico?",["Aumento de la masa ósea, que previene la osteoporosis","Engrosamiento del cartílago articular por aporte de colágeno","Acortamiento adaptativo de los tendones más solicitados"],["El curso cita el aumento de la masa ósea, que previene la osteoporosis, entre los efectos musculoesqueléticos.","El curso no describe ningún engrosamiento del cartílago: los efectos musculoesqueléticos que recoge atañen al hueso, al músculo y a la movilidad.","No se describe ningún acortamiento tendinoso: la carga de entrenamiento no se presenta como una exigencia de retracción."]],
  "53": ["¿Qué efecto cardiovascular produce el ejercicio terapéutico a largo plazo?",["Reducción de la frecuencia cardiaca basal","Aumento permanente de la presión arterial basal","Disminución de la capacidad aerobia"],["El ejercicio sistemático produce adaptaciones que reducen la frecuencia cardiaca basal.","El aumento de la presión es solo un efecto a corto plazo, no una adaptación duradera.","El curso describe un aumento de la capacidad aerobia y de la resistencia."]],
  "54": ["¿Cómo actúa el ejercicio terapéutico sobre el dolor (sistema neuromuscular)?",["Libera endorfinas y activa los controles central y periférico del dolor","Aumenta la inflamación local para enmascarar el dolor","Bloquea definitivamente la conducción de las fibras nociceptivas"],["El curso cita la liberación de endorfinas y la activación de los mecanismos centrales y periféricos.","El curso indica una reducción de la inflamación, no un aumento.","El efecto es una hipoalgesia transitoria, no un bloqueo definitivo de las fibras."]],
  "55": ["¿Cuál es el objetivo principal del masaje sedante o relajante?",["Sedar el dolor actuando sobre las terminaciones nerviosas de la piel","Recuperar el tono, el volumen y la fuerza muscular","Estimular los sistemas nervioso y circulatorio"],["El curso define ese masaje como aquel que seda el dolor a través de las terminaciones nerviosas cutáneas.","Es el objetivo del masaje tonificante, no del sedante.","Es el objetivo del masaje estimulante."]],
  "56": ["¿Cuál es el efecto del drenaje linfático manual?",["Activación del flujo linfático y reabsorción del líquido intersticial","Aumento de la acción del sistema nervioso simpático","Aumento de la frecuencia cardiaca"],["El curso describe la movilización del líquido intersticial y la activación del flujo linfático.","El curso indica una reducción de la acción simpática (relajación).","El curso describe una disminución de la frecuencia cardiaca (efecto parasimpático)."]],
  "57": ["Según los grados de Maitland, ¿cuál es el objetivo de una movilización de grado I?",["Reducir el dolor y desensibilizar la articulación en los estados irritables","Ganar los últimos grados de movilidad capsular","Aumentar la movilidad cuando predomina la rigidez"],["El grado I (pequeña amplitud, inicio del recorrido) busca disminuir el dolor y desensibilizar.","Es el objetivo del grado IV (pequeña amplitud al final del recorrido).","Es el objetivo del grado III (gran amplitud hasta la barrera)."]],
  "58": ["Según la teoría de la compuerta, ¿qué fibras se estimulan para inhibir la transmisión del dolor?",["Las fibras A-beta del tacto y de la presión","Las fibras A-delta del dolor agudo","Las fibras C del dolor sordo"],["El curso indica que las fibras A-beta, de gran diámetro, del tacto y de la presión, activan la interneurona inhibidora del asta dorsal y cierran así la compuerta al dolor.","Las fibras A-delta transmiten el dolor agudo; no cierran la compuerta.","Las fibras C transmiten el dolor sordo y continuo; no inhiben la transmisión."]],
  "59": ["En electroterapia, ¿con qué finalidad se emplean las altas frecuencias (superiores a 50 Hz)?",["La analgesia","La electroestimulación muscular","La producción de una corriente galvánica continua"],["El curso precisa que las altas frecuencias (>50 Hz) se emplean para la analgesia.","El curso reserva las bajas frecuencias (<50 Hz) a la electroestimulación.","La corriente galvánica es una corriente continua a 0 Hz, sin relación con la elección de frecuencia."]],
  "60": ["¿Qué tejidos se consideran buenos conductores de la corriente eléctrica?",["La sangre, la linfa y el músculo","El hueso, la grasa y la piel callosa","Los tendones, las fascias y el cartílago"],["El curso clasifica la linfa, la sangre y los músculos entre los buenos conductores (ricos en agua y electrolitos).","El curso los clasifica entre los malos conductores.","El curso los clasifica como conductores intermedios."]],
  "61": ["¿Cuál es un efecto neuroquímico de la neuroplasticidad en fisioterapia neurológica?",["Cambios en los neurotransmisores y los receptores","La pérdida definitiva de la eficacia sináptica","La ausencia de formación de nuevas sinapsis"],["El curso cita los cambios neuroquímicos: neurotransmisores y receptores.","El curso describe una mejora de la eficacia sináptica, no su pérdida.","El curso cita al contrario la creación de nuevas sinapsis (regeneración axonal)."]],
  "62": ["¿Cómo se define la plasticidad neuronal?",["La capacidad del sistema nervioso de cambiar de función y de estructura en respuesta a los estímulos","La degradación irreversible de las conexiones neuronales tras una lesión","La transmisión fija e inmutable de los mensajes nerviosos"],["El curso define la plasticidad como ese cambio de funcionalidad y de estructura frente a los estímulos.","El curso describe una adaptación, no una degradación irreversible.","La plasticidad implica precisamente una modificación, no una transmisión inmutable."]],
  "63": ["¿Cuál es un efecto fisiológico de la fisioterapia respiratoria sobre el intercambio gaseoso?",["Mejora de la oxigenación de los tejidos y reducción de la hipercapnia","Aumento de la hiperinsuflación pulmonar","Disminución del aclaramiento mucociliar"],["El curso cita la mejora de la oxigenación y la reducción de la hipercapnia.","El curso indica al contrario una disminución de la hiperinsuflación pulmonar.","El curso busca favorecer el aclaramiento mucociliar, no disminuirlo."]],
  "64": ["¿Qué efecto fisiológico produce la fisioterapia respiratoria sobre la ventilación?",["Aumento de la ventilación alveolar","Aumento de la intensidad percibida de la disnea","Reducción de la capacidad de ejercicio"],["El curso cita el aumento de la ventilación alveolar como efecto sobre la ventilación.","El curso indica una reducción de la disnea percibida.","El curso describe una mejora de la capacidad de ejercicio."]],
  "65": ["Entre los efectos mecánicos de la punción seca, ¿cuál se describe en el curso?",["Eliminación de las sustancias sensibilizantes como la sustancia P","Descenso del pH en los puntos gatillo","Disminución de la circulación sanguínea del músculo"],["El curso cita la eliminación de las sustancias sensibilizantes (sustancia P, bradicinina).","El curso describe una elevación del pH en los puntos gatillo, no un descenso.","El curso indica una mejora de la circulación y de la oxigenación musculares."]],
  "66": ["¿Cuál es el mecanismo de acción de la electrólisis percutánea?",["Una corriente galvánica que provoca una reacción inflamatoria controlada que estimula la reparación","Una ablación térmica del tejido mediante corriente de alta frecuencia","La inyección de una sustancia analgésica a través de la aguja"],["El curso describe la aplicación de una corriente galvánica que induce una inflamación controlada reparadora.","El procedimiento es electroquímico mediante una corriente galvánica, no una ablación térmica.","No se inyecta ninguna sustancia; el efecto proviene de la corriente galvánica."]],
  "67": ["Según el curso, ¿quién realizó la primera descripción que reúne todos los medios o agentes físicos en el marco de la fisioterapia (1921)?",["Gilbert y Carnot","Max Herz","Nogier"],["El curso atribuye a Gilbert y Carnot, en 1921, la primera aglutinación de todos los agentes físicos en la fisioterapia.","Max Herz, profesor en Viena, mencionó los métodos fisioterápicos a comienzos del siglo XX, pero no esa descripción conjunta de 1921.","Nogier se cita como referencia bibliográfica (electroterapia), no como autor de esa primera descripción."]],
  "68": ["Según Max Herz, lo que caracteriza a las materias fisioterápicas no es un sistema de órganos ni un tipo de afección, sino:",["el dominio y el manejo exclusivos de una técnica terapéutica específica","la dependencia jerárquica respecto del médico","el uso exclusivo de medicamentos específicos"],["Herz define esas materias por el dominio y el manejo exclusivos de una técnica terapéutica específica.","La dependencia del médico rehabilitador se menciona en otro lugar como un freno, no como el criterio de Herz.","Al contrario, Herz habla de « terapéutica sin medicamentos » o « arte de curar sin medicamentos »."]],
  "69": ["Según el curso, ¿cómo califica Max Herz los métodos fisioterápicos en relación con los medicamentos?",["Terapéutica sin medicamentos, o arte de curar sin medicamentos","Terapéutica complementaria a los medicamentos","Terapéutica basada en los medicamentos físicos"],["Herz habla de « terapéutica sin medicamentos » o « arte de curar sin medicamentos ».","El curso no menciona una complementariedad, sino una terapéutica sin medicamentos.","El término empleado es « sin medicamentos », no « medicamentos físicos »."]],
  "70": ["Entre las categorías de agentes físicos, ¿a cuál pertenecen las corrientes alternas y continuas, los infrarrojos y el láser?",["Los agentes electromagnéticos","Los agentes cinéticos","Los agentes elementales"],["El curso clasifica los recursos eléctricos (corrientes, infrarrojos, ultravioletas, láser) entre los agentes electromagnéticos.","Los agentes cinéticos corresponden al movimiento (movilizaciones, trabajo activo), no a las corrientes y radiaciones.","Los agentes elementales son los que se encuentran en la naturaleza (calor, frío, agua), no las corrientes eléctricas."]],
  "71": ["Según el curso, los agentes físicos electromagnéticos reúnen los recursos eléctricos en todas sus formas, con excepción:",["de las radiaciones ionizantes","de las corrientes continuas","del láser"],["El curso precisa que la categoría electromagnética excluye las radiaciones ionizantes.","Las corrientes continuas forman parte de los agentes electromagnéticos; no quedan excluidas.","El láser se cita como ejemplo de agente electromagnético; no queda excluido."]],
  "72": ["Según el curso, ¿a qué ámbito no está realmente vinculada la fisioterapia, aunque ese vínculo inicial haya condicionado su desarrollo?",["Los cuidados de enfermería","La farmacología","La radiología"],["El curso indica que la fisioterapia no está vinculada a los cuidados de enfermería, pero que ese vínculo inicial condicionó su desarrollo.","El curso no menciona la farmacología como vínculo inicial que haya condicionado el desarrollo de la profesión.","El curso no menciona la radiología como vínculo histórico que haya deformado la percepción de la profesión."]],
  "73": ["Según el curso, ¿qué diferencia esencial separa al fisioterapeuta del personal de enfermería?",["El fisioterapeuta busca una respuesta orgánica de curación; la enfermería proporciona acciones que la persona no puede o no sabe hacer por sí misma","El fisioterapeuta concibe cuidados; la enfermería busca una respuesta orgánica","Ambos persiguen únicamente la misma respuesta orgánica de curación"],["El curso opone la búsqueda de una respuesta orgánica curativa (fisioterapia) al hecho de suplir a la persona (enfermería).","Es al contrario: la enfermería concibe y aplica cuidados, y el fisioterapeuta busca la respuesta orgánica.","El curso subraya al contrario una diferencia de finalidad entre ambas profesiones."]],
  "74": ["Según la ley 44/2003 citada en el curso, los tratamientos del fisioterapeuta buscan la recuperación y la readaptación de las personas que padecen:",["disfunciones somáticas o discapacidades, así como su prevención","únicamente enfermedades infecciosas agudas","exclusivamente trastornos psiquiátricos"],["La ley 44/2003 menciona las disfunciones somáticas o discapacidades y su prevención.","La ley no restringe la fisioterapia a las enfermedades infecciosas agudas.","La ley se refiere a las disfunciones somáticas o discapacidades, no exclusivamente a los trastornos psiquiátricos."]],
  "75": ["Según la definición de la OMS (1968) citada en el curso, la fisioterapia es el arte y la ciencia del tratamiento mediante:",["el ejercicio terapéutico, el calor, el frío, el agua, el masaje y la electricidad","los medicamentos y la cirugía reparadora","las radiaciones ionizantes y la radioterapia"],["La definición de la OMS (1968) enumera el ejercicio terapéutico, el calor, el frío, el agua, el masaje y la electricidad.","La OMS no menciona los medicamentos ni la cirugía en esa definición de la fisioterapia.","La OMS de 1968 no cita las radiaciones ionizantes en su definición."]],
  "76": ["Según la WCPT (1999) citada en el curso, ¿qué constituye la base de lo que se considera sano?",["Un movimiento completo y funcional","La ausencia total de todo dolor","La toma regular de tratamientos físicos"],["La WCPT (1999) considera que un movimiento completo y funcional es la base de lo que es sano.","El curso no define la salud por la ausencia de dolor, sino por el movimiento funcional.","La base admitida es el movimiento funcional, no la toma de tratamientos."]],
  "77": ["Según la definición de ciencia dada en el curso, los principios y leyes deducidos deben tener una capacidad:",["predictiva y verificable experimentalmente","intuitiva y no reproducible","subjetiva y personal"],["La definición (RAE) precisa leyes con una capacidad predictiva y verificable experimentalmente.","La ciencia exige al contrario una verificación experimental, no la intuición no reproducible.","El conocimiento científico se caracteriza por la objetividad, no por la subjetividad."]],
  "78": ["Según el curso, la característica radical de una ciencia, que permite superar un simple conocimiento superficial, es:",["el hecho de tener un método","el hecho de basarse en la intuición cotidiana","el hecho de acumular hechos sin orden"],["El curso afirma que la característica radical de la ciencia es tener un método: Ciencia = Conocimiento + Método.","El pensamiento cotidiano no busca explicaciones profundas; no es eso lo que define la ciencia.","La sistematicidad exige al contrario un conjunto ordenado y relacionado, no una acumulación sin orden."]],
  "79": ["Según el curso, ¿cuáles son los dos pilares fundamentales en los que se basa el método científico?",["La reproducibilidad y la refutabilidad","La subjetividad y la intuición","La tradición y la autoridad"],["El curso identifica la reproducibilidad y la refutabilidad como los dos pilares del método científico.","El método científico es objetivo y se basa en pruebas, no es subjetivo ni intuitivo.","El curso no fundamenta el método científico en la tradición ni en la autoridad, sino en la reproducibilidad y la refutabilidad."]],
  "80": ["Según el curso, ¿qué indicio hallado en un esqueleto prehistórico (callo óseo) se interpreta como señal de la aparición de la empatía en el ser humano?",["Una marca de reparación de fractura","Una huella de trepanación craneal","Un amuleto colocado junto al cuerpo"],["El callo óseo atestigua que un miembro del grupo ayudó al herido a recuperarse, señal de empatía.","El curso habla de un callo óseo que repara una fractura, no de una trepanación del cráneo.","Los amuletos se mencionan en la Edad Media profana, no como indicio de empatía prehistórica."]],
  "81": ["Según el curso, ¿en qué se basaba principalmente la medicina empírica aparecida en la prehistoria?",["La experiencia y la observación de efectos que parecían beneficiosos","La teoría de los cuatro humores","La lectura de textos racionales escritos"],["Empleaba agentes físicos (calor, frío, agua), basándose en la experiencia y la observación.","La teoría de los humores proviene del Corpus hipocrático en la Grecia antigua, no de la prehistoria.","La escritura aparece con los sumerios; la medicina primitiva era empírica, sin textos."]],
  "82": ["Según el curso, ¿a qué civilización antigua se atribuye el dedo gordo de Greville Chester, presentado como la primera prótesis de la historia?",["El Egipto antiguo","Los sumerios","La América precolombina"],["El dedo gordo de Greville Chester (siglo XIII a. C.) se cita para el Egipto antiguo.","Los sumerios se citan por la escritura cuneiforme y la rueda, no por esa prótesis.","Las civilizaciones precolombinas empleaban duchas de vapor y exorcismos, no esa prótesis."]],
  "83": ["Según el curso, ¿qué práctica terapéutica empleaban los aztecas (América antigua)?",["Duchas de vapor seguidas de duchas frías","Baños de mar contra las afecciones de las glándulas","Masajes con aceites aromáticos"],["El curso indica que los aztecas empleaban duchas de vapor seguidas de duchas frías.","El agua de mar contra las glándulas se atribuye a Richard Russell, en la Edad Moderna.","El masaje con aceites aromáticos corresponde a la medicina ayurvédica de la India antigua."]],
  "84": ["Según el curso, ¿a qué emperador chino se le recomendaban ejercicios respiratorios y masajes contra la fiebre, los escalofríos y la parálisis?",["El emperador Amarillo Huangdi","Chu'n Yu","Tzu Kuo Shih"],["Huangdi, autor del Nei-Ching, recomienda ejercicios respiratorios y masajes contra la fiebre, los escalofríos y la parálisis.","Chu'n Yu escribió observaciones y preguntas y respuestas de terapia física, pero no esas recomendaciones.","Tzu Kuo Shih se asocia a la terapia QiGong y a la acupuntura, no a esas recomendaciones."]],
  "85": ["Según el curso, ¿qué médico de la Roma antigua se describe como un niño prodigio que « dogmatizó » la medicina durante los 1500 años siguientes?",["Galeno","Celso","Plinio el Viejo"],["El curso presenta a Galeno como un niño prodigio que dogmatiza la medicina durante 1500 años.","Celso recomendaba movilizaciones activas y pasivas, pero no se describe así.","Plinio el Viejo defendía la helioterapia y el solárium, no la dogmatización de la medicina."]],
  "86": ["Según el curso, ¿qué principio ético fundamental se asocia al juramento hipocrático mediante la fórmula « Primum non nocere »?",["La no maleficencia (no dañar)","La confidencialidad del secreto médico","La transmisión del saber a las generaciones futuras"],["« Primum non nocere » designa la no maleficencia: no dañar al paciente.","La confidencialidad es otro principio del juramento, pero distinto de « Primum non nocere ».","La enseñanza es un principio del juramento, pero no corresponde a esa fórmula."]],
  "87": ["Según el curso, ¿qué médico de la Edad Moderna desarrolló la primera prótesis de pierna y recomendaba el masaje del muñón del amputado?",["Ambroise Paré","Francisco Arceo","Andrés Vesalio"],["Ambroise Paré desarrolló la primera prótesis de pierna y recomendaba el masaje del muñón.","Arceo inventó la bota ortopédica para el pie equinovaro, con la ayuda de Paré.","Vesalio es el fundador de la anatomía moderna, no el autor de esa prótesis."]],
  "88": ["Según el curso, ¿qué autor español de la Edad Moderna escribió el « Libro del ejercicio corporal »?",["Cristóbal Méndez","Bernardino Gómez Miedes","Sebastián Busqué y Torró"],["Méndez escribe el « Libro del ejercicio corporal », obra mayor de la terapia física en España.","Gómez Miedes escribe el Enchiridion, manual contra la gota, no ese libro.","Busqué y Torró publica una gimnasia higiénica en el siglo XIX, siguiendo a Ling."]],
  "89": ["Según el curso, ¿qué médico que trabajaba sobre el raquitismo infantil presentó la técnica de suspensión y de tracción para enderezar la columna vertebral?",["Francis Glisson","Giovanni Alfonso","Joseph Duchenne"],["Glisson, que estudiaba el raquitismo, presentó la suspensión y la tracción para enderezar el raquis.","Alfonso se interesó por el Motus y la mecánica del movimiento en « Motus Animalis ».","Joseph Duchenne afirmaba que el ejercicio previene los dolores del reposo, sin esa técnica."]],
  "90": ["Según el curso, ¿qué médico se cita como tratante de la parálisis con corrientes eléctricas y describió la evolución del hombro congelado de su vecino mediante descargas eléctricas?",["Benjamin Franklin","Luigi Galvani","Christian Gottlieb Kratzenstein"],["Franklin trata la parálisis con corrientes eléctricas y describe el hombro congelado de su vecino.","Galvani, con Volta, descubre la excitabilidad muscular mediante la electricidad, sin ese caso clínico.","Kratzenstein se cita por la recuperación de una parálisis del quinto dedo de la mano."]],
  "91": ["Según el curso, ¿a qué fisiólogo se atribuye la corriente farádica, primera corriente alterna empleada en terapia?",["Faraday","Carlo Matteucci","Duchenne de Boulogne"],["El curso indica que Faraday introduce la corriente farádica, primera corriente alterna en terapia.","Matteucci estudia la electrólisis, la electroacupuntura y la electrofisiología, no esa corriente.","Duchenne de Boulogne trabaja sobre la faradización localizada y los puntos motores."]],
  "92": ["Según el curso, ¿quién se considera el padre de la hidroterapia, que fundó un centro en 1829 para aplicar el método hidropático?",["Vincenz Priessnitz","Louis Fleury","Sigmund Hahn"],["Priessnitz, padre de la hidroterapia, funda un centro en 1829 para el método hidropático.","Fleury hizo pasar la técnica de Priessnitz de una terapia empírica a científica.","Hahn describió el efecto del agua fría sobre el cuerpo en la Edad Moderna, sin ser ese padre."]],
  "93": ["Según el curso, ¿quién se considera el « padre de la osteopatía »?",["Andrew Taylor Still","Daniel David Palmer","August Paul von Wassermann"],["El curso presenta a Andrew Taylor Still como el padre de la osteopatía, que partió de los trabajos de Hipócrates.","Palmer, magnetizador, está en el origen de la quiropraxia, no de la osteopatía.","Wassermann compiló en 1928 los agentes físicos de la historia, sin fundar la osteopatía."]],
  "94": ["Según el curso, ¿qué método de 1943 trata primero la parálisis cerebral infantil y después a los adultos hemipléjicos?",["El método Bobath","El método Vojta","El método Klapp"],["Bobath (1943) trata la parálisis cerebral infantil y después a los adultos hemipléjicos.","Vojta (1970) es un diagnóstico y tratamiento precoz basado en la estimulación refleja.","Klapp (1904) atañe a la movilización para la escoliosis, no a la parálisis cerebral."]],
  "95": ["Según el curso, ¿a qué principio deben responder las distintas disciplinas en el trabajo interdisciplinar?",["Un principio de complementariedad","Un principio de jerarquía médica","Un principio de independencia total"],["El curso indica que las disciplinas deben responder a un principio de complementariedad, aceptando las capacidades y los límites de cada una.","El curso no fundamenta la interdisciplinariedad en una jerarquía, sino en la complementariedad.","El curso precisa al contrario que eso no significa ganancia ni pérdida de independencia, sino un enriquecimiento mutuo."]],
  "96": ["Según el curso, ¿qué profesionales intervienen típicamente en un programa interdisciplinar de manejo del dolor?",["Médicos, enfermeras, psicólogos, fisioterapeutas y terapeutas ocupacionales","Únicamente médicos y farmacéuticos","Únicamente cirujanos y anestesistas"],["El curso cita a esos profesionales entre quienes participan en los programas interdisciplinares del dolor.","El curso describe un equipo multiprofesional mucho más amplio que esos dos perfiles.","Esas especialidades no son la relación que da el curso para esos programas."]],
  "97": ["Según el curso, en el modelo biopsicosocial, ¿a qué dimensión pertenece el trabajo?",["A la dimensión social","A la dimensión biológica","A la dimensión psicológica"],["El curso clasifica el trabajo, la familia y la atención sanitaria en la dimensión social.","La dimensión biológica reúne medicamentos, ejercicio, cirugías y sueño, no el trabajo.","La dimensión psicológica atañe a la cognición, las emociones, la conducta y la atención."]],
  "98": ["Según el curso, ¿en qué consiste una relación interdisciplinar de tipo « parcial o lineal »?",["Una disciplina toma prestada una ley de otra para explicar un fenómeno","Varias disciplinas se fusionan para crear una nueva disciplina","Las disciplinas se tocan pero conservan sus límites"],["El curso define la relación parcial o lineal como el préstamo de una ley de una disciplina a otra (p. ej. termodinámica, gravedad).","Eso corresponde a la relación total o estructural, no a la relación parcial.","Eso describe la relación tangencial, no la relación parcial o lineal."]],
  "99": ["Según el curso, ¿dónde se inscriben en España los profesionales sanitarios regulados y cualificados?",["En el registro nacional de profesionales sanitarios","En el registro de profesiones liberales","En el registro de educadores de salud"],["El curso indica que esas profesiones se inscriben en el registro nacional de profesionales sanitarios, lo que garantiza la validez de sus títulos.","El curso menciona específicamente el registro nacional de profesionales sanitarios.","Ese registro no se cita en el curso para los profesionales sanitarios regulados."]],
  "100": ["Según el curso, la anamnesis (entrevista clínica) requiere un proceso de comunicación que es:",["Interpersonal y de doble sentido","De sentido único, del terapeuta hacia el paciente","Puramente escrito, sin intercambio verbal"],["El curso precisa que la anamnesis requiere un proceso de comunicación interpersonal de doble sentido.","El curso insiste en el doble sentido, no en una comunicación unidireccional.","La anamnesis es un diálogo verbal, no un simple intercambio escrito."]],
  "101": ["Según el curso, ¿qué tipo de entrevista clínica aplica rigurosamente preguntas predefinidas a todos los sujetos?",["La entrevista estructurada","La entrevista semiestructurada","La entrevista no estructurada"],["El curso indica que la entrevista estructurada emplea preguntas predefinidas aplicadas rigurosamente a todos los sujetos, con objetividad y fiabilidad elevadas.","La entrevista semiestructurada parte de preguntas planificadas pero adaptables; no se aplica rigurosamente.","La entrevista no estructurada es informal y flexible, sin preguntas rigurosamente predefinidas."]],
  "102": ["Según el curso, ¿cuál es un inconveniente de la entrevista clínica no estructurada?",["Pueden quedar lagunas en las informaciones necesarias","Carece de flexibilidad y de adaptación al sujeto","Impide toda relación terapéutica"],["El curso señala que la entrevista no estructurada puede dejar lagunas en los datos por recoger.","Esa falta de flexibilidad es el inconveniente de la entrevista estructurada, no de la no estructurada.","El curso no atribuye ese inconveniente a la entrevista no estructurada."]],
  "103": ["Según el curso, ¿qué distancia se recomienda entre el fisioterapeuta y el paciente durante la entrevista?",["Unos 50 a 100 cm","Unos 10 a 30 cm","Unos 150 a 200 cm"],["El curso recomienda una distancia de unos 50 a 100 cm para preservar el « espacio burbuja » sin dar una sensación de frialdad.","Esa distancia sería demasiado corta e invadiría el espacio personal del paciente.","Esa distancia daría una sensación de frialdad o de desinterés según la lógica del curso."]],
  "104": ["Entre las actitudes básicas del terapeuta, ¿cómo define el curso la aceptación incondicional?",["Aceptar al paciente tal como es, sin juzgarlo, y apreciarlo como persona","Sentir la misma emoción que el paciente ante su problema","Comunicar sus propios sentimientos con sinceridad"],["El curso define la aceptación incondicional como aceptar al paciente sin juicio y apreciarlo como persona.","Eso se aproxima a la simpatía, distinta de la aceptación incondicional.","Eso corresponde a la autenticidad, otra actitud básica distinta."]],
  "105": ["Según el curso, ¿en qué consiste la habilidad de « clarificación » en la escucha?",["Pedir al paciente que precise el sentido de un mensaje vago o ambiguo","Resumir en otros términos el contenido principal del mensaje","Expresar los sentimientos del paciente, sean explícitos o implícitos"],["El curso define la clarificación como pedir al paciente que aclare un mensaje vago, ambiguo o implícito.","Eso corresponde a la paráfrasis, no a la clarificación.","Eso corresponde al reflejo, no a la clarificación."]],
  "106": ["Según el curso, ¿qué debe hacerse cuando una persona expone un problema por primera vez?",["Dejarla expresarse sin interrumpirla con peticiones frecuentes de aclaración","Formular de inmediato hipótesis firmes para ganar tiempo","Responder por anticipado a las informaciones aún no comunicadas"],["El curso aconseja dejar que el paciente se exprese y no interrumpirlo con peticiones frecuentes de clarificación en una primera exposición.","El curso cita al contrario la formulación de hipótesis firmes con pocos datos como un obstáculo para la escucha.","El curso presenta esa conducta como un obstáculo para una escucha eficaz."]],
  "107": ["Según el curso, en el « mapa corporal », ¿con qué códigos marca el paciente las zonas afectadas?",["Distintos códigos o colores según el tipo de síntoma","Únicamente una cruz negra sobre cada zona dolorosa","Cifras del 1 al 10 que indican la frecuencia horaria"],["El curso pide al paciente dibujar las zonas de dolor, parestesia, quemazón u hormigueo con distintos códigos o colores.","El curso prevé códigos o colores variados, no una marca única.","El curso no emplea una escala horaria numerada en el mapa corporal."]],
  "108": ["En el razonamiento deductivo se procede:",["de lo general hacia lo específico","de lo específico hacia lo general","sin punto de partida definido"],["El curso indica que el razonamiento deductivo parte de algo muy general para llegar a algo específico.","Es la definición del razonamiento inductivo, no del deductivo.","El razonamiento deductivo sí tiene un punto de partida general identificado."]],
  "109": ["Según el curso, ¿qué tipo de razonamiento se describe como muy complicado y difícil de poner en práctica?",["El razonamiento inductivo","El razonamiento deductivo","El razonamiento analógico"],["El curso califica el razonamiento inductivo (de lo específico a lo general) de muy complicado y muy difícil de poner en práctica.","El deductivo se presenta como el punto de partida habitual, no como el más difícil.","Ese tipo no se cita como el más difícil en el curso."]],
  "110": ["Según el curso, la experiencia en materia de razonamiento clínico:",["no se limita al número de años de trabajo","equivale al número de años de trabajo","depende únicamente de la frecuencia de las decisiones"],["El curso precisa que la experiencia no se limita al número de años de trabajo ni a la frecuencia de la toma de decisiones.","El curso dice precisamente lo contrario: no se reduce a los años de ejercicio.","El curso indica que no es sinónimo de una mayor frecuencia en la toma de decisiones."]],
  "111": ["Entre los posibles prejuicios del fisioterapeuta, ¿cuál se cita en el curso?",["El sesgo de confirmación","El sesgo de disponibilidad","El sesgo de anclaje"],["El curso enumera el sesgo de confirmación entre los prejuicios ligados a las creencias del fisioterapeuta.","Ese sesgo no se cita en la relación del curso.","Ese sesgo no se menciona entre los prejuicios enumerados por el curso."]],
  "112": ["En el factor PSICO del modelo biopsicosocial, ¿qué estrategia hay que intentar favorecer siempre en el paciente?",["Estrategias de afrontamiento activas","Estrategias de afrontamiento pasivas","La evitación de la actividad"],["El curso indica que hay que intentar siempre que el paciente ponga en práctica estrategias de afrontamiento activas, por ejemplo hacer ejercicio.","El curso prioriza las estrategias activas antes que las pasivas.","La evitación corresponde al modelo miedo-evitación, una adaptación negativa que hay que evitar."]],
  "113": ["Según el curso, ¿a qué factor del modelo biopsicosocial pertenece el nivel socioeconómico del paciente?",["Al factor social","Al factor biológico","Al factor psicológico"],["El curso clasifica el estatus o nivel socioeconómico y la educación entre los factores sociales.","El factor biológico atañe a la nocicepción, la inflamación y las pruebas de imagen.","El factor psicológico reúne la kinesiofobia, el catastrofismo y la ansiedad."]],
  "114": ["Según el curso, ¿qué modelo de razonamiento clínico no se adapta a la fisioterapia porque se basa en el diagnóstico?",["El modelo inicial","El modelo colaborativo","El modelo biopsicosocial"],["El curso indica que el modelo inicial, basado en el diagnóstico y en el razonamiento hipotético-deductivo, no se adapta a la fisioterapia, cuyo razonamiento se basa en la función.","El modelo colaborativo implica al paciente e integra los factores psicosociales; no se centra en el diagnóstico.","El modelo biopsicosocial es multidimensional y el curso no lo rechaza."]],
  "115": ["Según Jones y Magarey, ¿qué no hay que hacer ante el paciente?",["Encerrarse en un pensamiento único","Formular preguntas abiertas","Aclarar formulando más preguntas"],["El curso recomienda no encerrarse en un pensamiento único, so pena de oír solo lo que se quiere oír.","Formular preguntas abiertas es al contrario recomendado por el curso.","El curso aconseja precisamente aclarar las cosas formulando más preguntas."]],
  "116": ["Entre las 7 categorías de hipótesis, ¿a qué corresponde la hipótesis de la limitación funcional?",["Al rol, a las actividades y a la participación del paciente","A los mecanismos de nocicepción y de inflamación","Al trabajo y al ocio que perpetúan el dolor"],["El curso asocia la hipótesis de limitación funcional al rol, a las actividades y a la participación (partes BIO y PSICO).","Eso corresponde a la hipótesis de los mecanismos patobiológicos.","Eso corresponde a la hipótesis de los factores contribuyentes."]],
  "117": ["Según el curso, ¿cómo debe anunciarse el pronóstico al paciente?",["Dando un plazo más bien largo, sin prometer una curación del 100 %","Prometiendo una curación completa para tranquilizarlo","Anunciando el plazo más corto posible"],["El curso aconseja dar un plazo más largo y no decir nunca al paciente que se le va a curar al 100 %.","El curso desaconseja prometer una curación del 100 %.","El curso recomienda al contrario dar un plazo más largo."]],
  "118": ["Según el curso, la metacognición corresponde al proceso mediante el cual el clínico:",["se autorregula para pensar sus propios pensamientos de forma reflexiva","percibe y analiza los datos recogidos","moviliza sus conocimientos biomédicos adquiridos"],["El curso define la metacognición como el proceso de autorregulación del clínico para elaborar sus pensamientos de manera escéptica y reflexiva (pensar sobre sus pensamientos).","Eso corresponde a la cognición, no a la metacognición.","Eso corresponde a la base de conocimientos, no a la metacognición."]],
  "119": ["Según el curso, ¿en qué se distingue el ejercicio terapéutico del ejercicio físico?",["Busca prevenir o tratar patologías dentro de un plan de rehabilitación","Busca únicamente mejorar la condición física general","Se dirige a toda persona que desee mejorar su bienestar"],["El curso opone el ejercicio terapéutico (prevenir o tratar patologías, necesidades individuales) al ejercicio físico, orientado a la condición o el bienestar.","Es la definición del ejercicio físico, destinado a cualquier persona que desee mejorar su forma, no del ejercicio terapéutico.","Ese público corresponde al ejercicio físico; el ejercicio terapéutico se dirige a personas con una patología bajo supervisión médica."]],
  "120": ["En cuanto al efecto del ejercicio terapéutico sobre el sistema cardiovascular a corto plazo, se observa:",["Un aumento de la frecuencia cardiaca y de la presión arterial","Una reducción de la frecuencia cardiaca basal","Un aumento de la capacidad aerobia desde el principio"],["A corto plazo, el ejercicio aumenta la frecuencia cardiaca y la presión arterial según la intensidad y los grupos musculares implicados.","Es un efecto a largo plazo, ligado a las adaptaciones del miocardio, no la respuesta aguda.","La mejora de la capacidad aerobia es una adaptación a largo plazo, no un efecto inmediato."]],
  "121": ["Según el curso, la hipoalgesia generalizada inducida por el ejercicio se obtiene sobre todo mediante:",["El ejercicio aerobio a intensidad media-alta","Un estiramiento estático prolongado del músculo doloroso","Un fortalecimiento isométrico localizado en la zona lesionada"],["El curso indica que el ejercicio aerobio, sobre todo a intensidad media-alta, induce una hipoalgesia generalizada a todo el cuerpo.","El estiramiento no es el mecanismo descrito; es el ejercicio aerobio el que produce la hipoalgesia generalizada.","El fortalecimiento local no se cita como fuente de la hipoalgesia generalizada descrita en el curso."]],
  "122": ["Según el curso, ¿qué principio resume la idea de que « la dosis es más importante que el tipo de ejercicio »?",["La dosificación adecuada prima sobre la elección del tipo de ejercicio","El tipo de ejercicio prima siempre sobre su dosificación","La duración total prima sobre la individualización del programa"],["El curso recoge explícitamente que la dosis es más importante que el tipo de ejercicio realizado.","Es lo contrario de lo que recoge el curso, que prioriza la dosis.","El curso insiste en la individualización y la dosis, no en la duración total como factor primero."]],
  "123": ["Según el curso, ¿cuál es el objetivo principal del masaje tonificante?",["Recuperar el tono, el volumen, la contractilidad y la fuerza","Facilitar la eliminación de los desechos del metabolismo muscular","Estimular los sistemas nervioso y circulatorio"],["El masaje tonificante busca la recuperación del tono, del volumen, de la contractilidad y de la fuerza, mediante maniobras profundas y prolongadas.","Es el objetivo del masaje de drenaje, con maniobras lentas y centrípetas.","Es el objetivo del masaje estimulante, mediante maniobras cortas, energéticas y rápidas."]],
  "124": ["Según el curso, ¿qué tipo de masaje desvía la sangre hacia la periferia provocando una fuerte hiperemia?",["El masaje revulsivo","El masaje sedante","El masaje de drenaje"],["El masaje revulsivo facilita la descongestión desviando la sangre hacia la periferia, lo que produce una fuerte hiperemia y una liberación de histamina.","El masaje sedante calma el dolor mediante maniobras lentas y superficiales; no provoca una hiperemia intensa.","El masaje de drenaje favorece la eliminación de los desechos mediante maniobras centrípetas, sin hiperemia revulsiva."]],
  "125": ["Según el curso, una contraindicación de la masoterapia es:",["Una inflamación o infección aguda","Una rigidez articular posinmovilización","Una contractura muscular crónica"],["El curso enumera la inflamación y la infección agudas entre las contraindicaciones del masaje.","La rigidez posinmovilización es más bien una indicación del masaje, no una contraindicación.","La contractura crónica no se enumera como contraindicación; lo son los estados agudos o infecciosos."]],
  "126": ["Según el curso, la movilización articular de grado IV de Maitland busca:",["Ganar los últimos grados de movilidad capsular al final del recorrido","Disminuir el dolor en los estados muy irritables","Aumentar la movilidad cuando predomina la rigidez, sin llegar al final del recorrido"],["El grado IV, de pequeña amplitud al final del recorrido, busca ganar los últimos grados de movilidad capsular.","Es el objetivo del grado I (pequeña amplitud, inicio del recorrido), no del grado IV.","Eso describe el grado III (gran amplitud hasta la barrera), no el grado IV al final del recorrido."]],
  "127": ["Según el curso, ¿cuál es el principio de la tracción articular?",["Liberar la presión intracapsular y limitar los roces entre superficies","Desplazar la articulación más allá de su amplitud a gran velocidad","Seguir el movimiento fisiológico para reducir la rigidez"],["La tracción libera la presión intracapsular y limita los roces articulares, lo que reduce el dolor percibido con el movimiento.","Eso describe la manipulación articular, no la tracción.","Eso corresponde a la movilización simple, no a la tracción, que libera la presión intracapsular."]],
  "128": ["Según el curso, en electroterapia las bajas frecuencias (inferiores a 50 Hz) se emplean para:",["La electroestimulación muscular","La analgesia por control de la compuerta","La penetración de los tejidos profundos"],["El curso indica que las bajas frecuencias (<50 Hz) sirven para la electroestimulación, y las altas frecuencias (>50 Hz) para la analgesia.","La analgesia se obtiene con las altas frecuencias (>50 Hz), no con las bajas.","Son las altas frecuencias las que favorecen la penetración profunda y la tolerancia a intensidades mayores."]],
  "129": ["Según el curso, el efecto del polo negativo (cátodo) de una corriente con efecto polar es:",["Una reacción alcalina con vasodilatación y excitación","Una reacción ácida con vasoconstricción y sedación","Una coagulación por liberación de oxígeno"],["El cátodo produce una reacción alcalina, libera hidrógeno y provoca vasodilatación, respuesta inflamatoria y excitación.","Es el efecto del polo positivo (ánodo): reacción ácida, coagulación, vasoconstricción y sedación.","La coagulación y la liberación de oxígeno son efectos del ánodo, no del cátodo."]],
  "130": ["Según el curso, la electrólisis percutánea (EPI) aplica una corriente galvánica con el fin de:",["Provocar una reacción inflamatoria controlada que estimule la reparación tisular","Producir una contracción muscular por despolarización de la motoneurona","Bloquear la conducción nerviosa mediante una corriente de alta frecuencia"],["La aplicación de la corriente galvánica a través de la aguja desencadena una inflamación controlada local que estimula la reparación de los tejidos.","Es el principio de la electroestimulación neuromuscular, no de la electrólisis percutánea.","La electrólisis emplea una corriente galvánica continua a 0 Hz, no un bloqueo nervioso de alta frecuencia."]],
  "131": ["Según el curso, en el músculo denervado la electroterapia actúa:",["Directamente sobre la fibra muscular","Despolarizando la motoneurona a través de la placa motora","Estimulando las fibras sensitivas A-beta"],["En el músculo denervado se estimula directamente la fibra muscular para mantener su metabolismo hasta la reinervación.","Eso atañe al músculo sano con inervación normal, en el que se activa el nervio a través de la placa motora.","La estimulación de las fibras A-beta corresponde al control del dolor, no a la contracción del músculo denervado."]],
  "132": ["Según el curso, ¿cuál es un efecto mecánico de la punción seca a nivel del punto gatillo?",["La eliminación de sustancias sensibilizantes como la sustancia P","La modulación de la actividad del asta dorsal de la médula","La activación de la ínsula y del córtex somatosensorial"],["Entre los efectos mecánicos, la punción seca elimina las sustancias sensibilizantes (sustancia P, bradicinina) y eleva el pH local.","Es un efecto neurofisiológico de la punción seca, no un efecto mecánico.","Esa activación cerebral corresponde a los efectos neurofisiológicos, no a los mecánicos."]],
  "133": ["Según el curso, el dolor de tipo inflamatorio se caracteriza por:",["Una mejoría con los antiinflamatorios y el frío","Una mejoría con el calor y un aumento en reposo","Un dolor muy localizado que disminuye en reposo"],["El dolor inflamatorio se acompaña de calor, enrojecimiento y edema, y mejora con antiinflamatorios y frío.","Ese perfil (aumenta en reposo, mejora con el calor) corresponde al dolor isquémico.","Son las características del dolor mecánico (ON/OFF, localizado, disminuye en reposo)."]],
  "134": ["Para que una disciplina se considere una ciencia, debe reunir:",["un corpus de conocimientos propio, un ámbito de actuación y un método sistemático","un corpus de conocimientos propio, un ámbito de actuación y una tradición reconocida","un ámbito de actuación, un método sistemático y un consenso entre expertos"],["El curso enuncia exactamente esas tres exigencias para que una disciplina acceda al estatuto de ciencia.","La tradición no figura entre las exigencias del curso: lo que se requiere es el método sistemático de acceso al saber.","El consenso de expertos no sustituye al corpus de conocimientos propio que exige el curso."]],
  "135": ["En la jerarquía de la evidencia presentada en el curso, ¿qué tipo de estudio se considera el patrón de referencia para determinar la eficacia de una intervención?",["El ensayo controlado aleatorizado, en el que los participantes se reparten al azar","El ensayo clínico controlado, cuyos grupos se constituyen sin sorteo","El estudio de cohortes, que sigue a un grupo de sujetos a lo largo del tiempo"],["El curso lo describe como un estudio experimental de alto nivel y como el patrón de referencia de la eficacia de una intervención.","Compara sí a los sujetos tratados y no tratados, pero la ausencia de aleatorización lo sitúa por debajo del ensayo aleatorizado.","Sigue los resultados según la exposición a un factor o a una intervención, pero se sitúa más abajo en la pirámide."]],
  "136": ["En el proceso de cinco etapas de la práctica basada en la evidencia, la etapa « Appraise » consiste en:",["transformar una necesidad de información en una pregunta que pueda responderse","evaluar de forma crítica la validez y la aplicabilidad de las pruebas encontradas","buscar en las bases de datos las mejores pruebas disponibles"],["Eso corresponde a la etapa « Ask », la primera del proceso, que precede a la búsqueda de las pruebas.","Es la etapa de evaluación crítica, que incluye la determinación del nivel de evidencia científica.","Eso corresponde a la etapa « Acquire », que aporta el material que la etapa siguiente evaluará."]],
  "137": ["En el método científico tal como se describe en el curso, la fase de análisis de los datos consiste en:",["determinar si la hipótesis es correcta, incorrecta o necesita ajustes","examinar los datos recogidos para ver si apoyan o rechazan la hipótesis","realizar la intervención y recoger las muestras de las variables estudiadas"],["Es la fase de las conclusiones, que viene después del análisis de los datos.","El curso define esa fase como el análisis de los datos recogidos para ver si apoyan o rechazan la hipótesis.","Es la fase de experimentación, que precede al análisis de los datos."]],
  "138": ["¿Qué efecto produce el ejercicio terapéutico sobre el metabolismo?",["Disminuye la masa muscular y ralentiza el gasto energético","Aumenta la masa grasa y rebaja el metabolismo basal","Mejora la sensibilidad a la insulina y ayuda a regular la glucemia"],["El ejercicio terapéutico aumenta la masa muscular, lo que mejora el metabolismo basal.","El curso describe lo contrario: pérdida de grasa corporal, ganancia de masa muscular y mejora del metabolismo basal.","El curso recoge ese efecto como beneficioso en personas diabéticas o con riesgo de diabetes."]],
  "139": ["Según el curso, la hipoalgesia inducida por el ejercicio aparece durante la sesión y puede persistir:",["hasta unas dos horas","hasta unas doce horas","hasta unos 30 minutos"],["No se enseña ninguna duración de ese orden: el efecto descrito se limita a unos treinta minutos.","Esa duración supera con mucho la ventana descrita en el curso, que es de unos 30 minutos.","El curso precisa que el efecto se produce durante la sesión de ejercicio y puede durar hasta 30 minutos."]],
  "140": ["¿Qué efecto produce el ejercicio terapéutico sobre el sistema respiratorio?",["Aumenta la capacidad pulmonar y facilita la eliminación del dióxido de carbono","Incrementa la retención de dióxido de carbono con un entrenamiento específico","Reduce la capacidad pulmonar mejorando a la vez la oxigenación de los tejidos"],["El curso recoge el aumento de la capacidad pulmonar, la mejora de la oxigenación y la eliminación del CO2.","El entrenamiento específico mejora la función de los músculos respiratorios y por tanto la eliminación del CO2.","La capacidad pulmonar aumenta con el ejercicio: el curso no describe ninguna reducción."]],
  "141": ["¿Qué se afirma de los efectos fisiológicos de la manipulación articular?",["Se conocen mal y no exigen la cavitación para producir analgesia","Se basan en la lubricación de las superficies por producción de líquido sinovial","Resultan de la liberación de la presión intracapsular de la articulación"],["El curso indica que los efectos no se conocen con precisión y que el fenómeno de cavitación no es necesario para la analgesia.","El curso atribuye ese efecto a la movilización articular analítica, no a la manipulación.","Es el principio de la tracción articular, descrita por separado en el curso."]],
  "142": ["Entre los efectos fisiológicos de la movilización articular analítica, se recoge:",["el aumento de la laxitud articular y la lubricación de las superficies articulares","la reabsorción del líquido intersticial y la activación del flujo de los linfangiones","la reducción de la excitabilidad neuromuscular y el descenso de la tasa de cortisol"],["El curso cita la activación del sistema Top-Down, la compuerta de control, el aumento de la laxitud y la producción de líquido sinovial.","Esos efectos de drenaje son los del drenaje linfático manual, no los de la movilización analítica.","Esos efectos figuran en el curso entre los del masaje clásico."]],
  "143": ["En una célula excitable, ¿qué caracteriza al potencial de acción frente al potencial graduado?",["Corresponde a la diferencia de carga entre el interior y el exterior en reposo","Su amplitud y su duración varían según la intensidad del estímulo aplicado","Responde a la ley del todo o nada y conserva siempre la misma intensidad"],["Es el potencial de reposo, situado normalmente entre -60 y -90 mV.","Es la definición del potencial graduado, que solo desencadena una respuesta si supera el umbral de excitación.","El curso precisa que, una vez desencadenado, el potencial de acción es un fenómeno « todo o nada », siempre de la misma intensidad."]],
  "144": ["Las corrientes interferenciales de Kotz (protocolo ruso) asocian dos frecuencias medias con el fin de obtener:",["una corriente unidireccional de 0 Hz con finalidad polar","una frecuencia de batido de 50 Hz con finalidad excitomotora","una frecuencia de batido de 100 Hz con finalidad analgésica"],["Una corriente continua de 0 Hz no se obtiene por interferencia de dos frecuencias medias.","El curso indica 2500 Hz + 2550 Hz, es decir una frecuencia de batido de 50 Hz, con finalidad excitomotora (protocolo ruso, reservado a los balances musculares más altos).","Es el resultado de las interferenciales de Nemec, que asocian 4000 Hz y 4100 Hz."]],
  "145": ["Según el curso, ¿cómo se aplica el TENS analgésico (100-150 Hz) según el tipo de dolor?",["En trenes en ambos casos, rebajando la frecuencia a 50 Hz","En modo continuo en los dolores crónicos y en trenes en los dolores agudos","En modo continuo en los dolores agudos y en trenes en los dolores crónicos"],["La frecuencia de 50 Hz corresponde al TENS excitomotor y no al TENS analgésico.","Las dos modalidades están invertidas respecto de lo que enseña el curso.","El curso asocia el modo continuo al dolor agudo y la aplicación en trenes (burst) al dolor crónico."]],
  "146": ["¿Cómo actúan las corrientes de alta frecuencia (más allá de 100 000 Hz)?",["Producen efectos polares con reacción ácida y reacción alcalina","No despolarizan la membrana nerviosa y actúan mediante producción de calor","Despolarizan las motoneuronas y provocan una contracción muscular"],["Los efectos polares exigen un flujo que circule en un solo sentido: corriente continua o corriente alterna asimétrica desequilibrada.","El curso indica que la alta frecuencia no despolariza la membrana y que los tejidos que se oponen a su paso se calientan.","Es el modo de acción de las bajas frecuencias empleadas en la electroestimulación del músculo inervado."]],
  "147": ["Según el curso, ¿por qué la intensidad aplicada en frecuencia media no debe superar los 20 mA?",["Porque más allá de ese umbral la membrana permanece en periodo refractario permanente","Porque cuanto más elevada es la corriente, más aumenta el calor desprendido, con riesgo de quemadura","Porque más allá de ese umbral la impedancia de la piel aumenta y bloquea la corriente"],["El periodo refractario depende de la frecuencia de los impulsos, no de la intensidad aplicada.","El curso recuerda la ley de Joule: más corriente significa más calor, de ahí el límite de 20 mA para evitar la quemadura.","El curso enseña lo contrario: la impedancia cutánea disminuye cuando la frecuencia aumenta."]],
  "148": ["Entre los objetivos de la fisioterapia respiratoria, se recoge:",["prevenir las disfunciones respiratorias y optimizar la función ventilatoria","corregir las deformidades torácicas y restaurar la movilidad articular costal","suprimir la producción de secreciones bronquiales y abolir la sensación de disnea"],["El curso fija como objetivos la prevención de las disfunciones, la optimización de la función pulmonar y ventilatoria y la mejora del aclaramiento mucociliar.","La corrección ortopédica no es un objetivo recogido por el curso, que apunta a la función ventilatoria y al drenaje.","El curso habla de mejorar el aclaramiento mucociliar y la sensación de disnea, no de suprimirlos."]],
  "149": ["¿Cuáles son los cuatro grandes grupos de técnicas de la fisioterapia respiratoria?",["Drenaje de las secreciones, aerosolterapia, oxigenoterapia y fortalecimiento muscular general","Drenaje de las secreciones, reeducación respiratoria, relajación respiratoria y fortalecimiento muscular","Reeducación respiratoria, relajación respiratoria, masaje torácico y ventilación mecánica"],["La aerosolterapia y la oxigenoterapia no figuran entre los grupos de técnicas enseñados.","Son las cuatro familias de técnicas presentadas en el curso.","El masaje torácico y la ventilación mecánica no forman parte de los cuatro grupos descritos."]],
  "150": ["¿De qué depende la elección de una técnica de fisioterapia respiratoria durante la evaluación del paciente?",["De la edad, de la cooperación y la tolerancia, de la gravedad y de la enfermedad","De la edad, del sexo, del índice de masa corporal y del nivel de actividad","De la gravedad, de la duración del ingreso, del tratamiento y del lugar de residencia"],["El curso recoge precisamente esos elementos de evaluación para orientar la elección técnica.","El sexo y el índice de masa corporal no figuran entre los criterios de evaluación enseñados.","Esos parámetros no son los que recoge el curso: insiste en la cooperación y la tolerancia del paciente."]],
  "151": ["¿Qué técnicas se emplean para la permeabilización de las vías respiratorias?",["Las técnicas manuales de bajo y de alto flujo, la presión espiratoria positiva y su variante oscilatoria","La presión espiratoria oscilatoria, la ventilación no invasiva y el entrenamiento de los músculos inspiratorios","Las técnicas manuales de bajo flujo, la aspiración traqueal y la humidificación de las vías aéreas"],["El curso enumera esas tres modalidades (técnicas manuales, PEP, PEP oscilatoria) en concepto de higiene bronquial.","La ventilación no invasiva y el entrenamiento inspiratorio corresponden a efectos distintos de la higiene bronquial.","La aspiración y la humidificación no figuran entre las técnicas de permeabilización citadas."]],
  "152": ["¿Por qué la fisioterapia respiratoria del lactante se orienta sobre todo al drenaje de las secreciones?",["Por la frecuencia de las deformidades ortopédicas del tórax a esa edad","Por las particularidades anatómicas y fisiológicas de su sistema respiratorio","Por la inmadurez aislada de sus músculos inspiratorios accesorios"],["Las deformidades ortopédicas atañen a los niños con una deficiencia neurológica grave.","El curso justifica la prioridad dada al drenaje por las particularidades fisiológicas y anatómicas del sistema respiratorio del lactante.","El curso no recoge ese motivo: invoca el conjunto de las particularidades anatómicas y fisiológicas."]],
  "153": ["En el niño con una deficiencia neurológica grave, la fisioterapia respiratoria se orienta a:",["la prevención de la obstrucción bronquial y la patología restrictiva ligada a las deformidades","la reeducación de la tos voluntaria y la relajación respiratoria torácica con prioridad","el fortalecimiento exclusivo de los músculos inspiratorios y la tolerancia al esfuerzo"],["El curso describe esa doble orientación en los niños con una afectación neurológica grave.","El curso destaca el manejo de la obstrucción bronquial y del componente restrictivo, no esos dos ejes.","El fortalecimiento muscular es un efecto esperado de la disciplina, pero no es la orientación descrita en esa población."]],
  "154": ["¿Qué efecto tiene la fisioterapia respiratoria sobre la capacidad funcional y la calidad de vida?",["Reduce la intensidad percibida de la disnea, pero disminuye la tolerancia al ejercicio","Aumenta la capacidad de ejercicio y reduce la intensidad percibida de la disnea","Aumenta la capacidad de ejercicio sin modificar la intensidad percibida de la disnea"],["La capacidad de ejercicio, al contrario, mejora según el curso.","El curso recoge la mejora de la capacidad de ejercicio, de la calidad de vida relacionada con la salud y el descenso de la disnea percibida.","La reducción de la intensidad percibida de la disnea forma parte de los efectos esperados."]],
  "155": ["Según el curso, entre los efectos fisiológicos de la fisioterapia respiratoria, ¿cuál cuenta con un nivel de evidencia A?",["El fortalecimiento de la musculatura respiratoria y de la musculatura general","La mejora del intercambio gaseoso con reducción de la hipercapnia","La mejora del aclaramiento mucociliar y de la permeabilización bronquial"],["El curso atribuye explícitamente un nivel de evidencia A al fortalecimiento muscular respiratorio y general.","Ese efecto está bien descrito, pero el curso no le asocia ningún nivel de evidencia A.","Ese efecto figura entre los de la disciplina, sin la mención del nivel de evidencia A."]]
});
